// Writes data/Plates.lua for the addon from plans/plates-mf.js:  node dev/elle-config/emit-plates.js
const fs = require('fs');
const path = require('path');
const L = require('./src/luatable.js');

function emit(plan) {
  const lines = [
    '-- GENERATED by dev/elle-config/emit-plates.js from dev/elle-config/plans/plates-mf.js. Do not edit by hand.',
    '-- MF Nameplates settings, applied by /qb layout apply (modules/Loadout.lua).',
    'local _, QB = ...',
    'QB.platesData = {',
    '  v = 1,',
    '  name = ' + L.lua(plan.name) + ',',
    '  sets = {',
  ];
  const seen = new Set();
  for (const [p, value] of plan.sets) {
    if (!Array.isArray(p) || !p.length || p.some((k) => typeof k !== 'string' && typeof k !== 'number')) throw new Error('bad path: ' + JSON.stringify(p));
    if (value === null || value === undefined || typeof value === 'object') throw new Error('only plain values are written: ' + p.join('.'));
    const key = JSON.stringify(p);
    if (seen.has(key)) throw new Error('the same setting twice: ' + p.join('.'));
    seen.add(key);
    lines.push('    { path = { "profiles", "$profile", ' + p.map((x) => L.lua(x)).join(', ') + ' }, value = ' + L.lua(value) + ' },');
  }
  lines.push('  },', '  removes = {', '  },', '}', '');
  return { text: lines.join('\n'), sets: plan.sets.length };
}
module.exports = { emit };
if (require.main === module) {
  const r = emit(require('./plans/plates-mf.js'));
  fs.writeFileSync(path.join(__dirname, '..', '..', 'data', 'Plates.lua'), r.text);
  console.log('wrote data/Plates.lua:', r.sets, 'values');
}
